def components(gi, color):
    H=len(gi); W=len(gi[0]); seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c]==color and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
