def solve(gi):
    H=len(gi); W=len(gi[0])
    out=[row[:] for row in gi]
    for color in sorted({x for row in gi for x in row}):
        if color==0: continue
        comps=components(gi,color)
        if len(comps)<2: continue
        for A in comps:
            for B in comps:
                if A is B or A>B: continue
                def ov(xmin,xmax,ymin,ymax): return not (xmax<ymin or xmin>ymax)
                # vertical relation: share column band
                if ov(min(a[1] for a in A), max(a[1] for a in A),
                       min(b[1] for b in B), max(b[1] for b in B)):
                    rlo=max(min(a[0] for a in A), min(b[0] for b in B))
                    rhi=min(max(a[0] for a in A), max(b[0] for b in B))
                    for c in sorted({a[1] for a in A}|{b[1] for b in B}):
                        for r in range(rlo, rhi+1):
                            if gi[r][c]==0: out[r][c]=color
                # horizontal relation: share row band
                if ov(min(a[0] for a in A), max(a[0] for a in A),
                       min(b[0] for b in B), max(b[0] for b in B)):
                    clo=max(min(a[1] for a in A), min(b[1] for b in B))
                    chi=min(max(a[1] for a in A), max(b[1] for b in B))
                    for r in sorted({a[0] for a in A}|{b[0] for b in B}):
                        for c in range(clo, chi+1):
                            if gi[r][c]==0: out[r][c]=color
    return out

